args.command:
python3 - <<'PY'
import workcell, math
pts={}
for n in ['M1','M2','M3','M4','M5','M6']:
    r=workcell.call('robot','locate',n)
    pts[n]=(r.data['x'],r.data['y'])
    print(n, r.data)
# manual simple: compute differences
def d(a,b):
    xa,ya=pts[a]; xb,yb=pts[b]
    return (xb-xa, yb-ya, math.hypot(xb-xa,yb-ya))
for a,b in [('M1','M2'),('M2','M3'),('M4','M5'),('M5','M6'),('M4','M1'),('M5','M2'),('M6','M3'),('M1','M3'),('M4','M6')]:
    dx,dy,l=d(a,b)
    ang=math.degrees(math.atan2(dy,dx))
    print(f"{a}-{b} dx={dx:.4f} dy={dy:.4f} len={l:.4f} ang={ang:.4f}")
PY

